INSERT INTO consent_templates (id, store_id, title, description, sections, form_fields, version, is_active)
VALUES (
  'test-consent-001',
  '801ff22a-cf24-4117-91e0-1e13462366cd',
  '施術同意書',
  '施術同意書の確認とご提出',
  '[{"title":"個人情報について","items":["(1) 当サロンは、個人情報保護法令を遵守し、お客様の情報を適切に保護する努力をいたします。","(2) 最終来店日より2年経過後、カルテを廃棄する場合があります。","(3) 取得した情報は、施術記録の確認、お問い合わせへの回答、サービスに関するご連絡の目的で使用いたします。","(4) お客様の同意がない限り、個人情報を第三者に提供することはありません。"]},{"title":"パリジェンヌ注意事項","items":["(1) パリジェンヌは優しい薬剤を使用し、まつ毛を根本から約80度立ち上げる技術です。","(2) 妊娠中・生理中・体調不良時・薬剤アレルギーがある方は、施術前にお申し出ください。","(3) レーシック手術後3ヶ月以内、アートメイク施術後1ヶ月以内の方は施術をお断りする場合があります。","(4) 施術当日にマスカラをご使用の場合、薬剤の浸透が低下する可能性があります。","(5) コンタクトレンズを着用されている方は、必ず事前にお申し出ください。","(6) 持続期間の目安は約4〜6週間です（個人差があります）。","(7) 施術後の返金・払い戻しはお受けしておりません。","(8) 施術写真をSNS等に掲載させていただく場合があります。掲載NGの方は事前にお申し出ください。"]},{"title":"まつ毛エクステ注意事項","items":["(1) まつ毛には毛周期があり、自然に抜け落ちることがあります。","(2) アレルギー体質の方はパッチテストをお勧めいたします。","(3) 眼疾患・逆さまつ毛・傷んだまつ毛の状態によっては、施術を制限させていただく場合があります。","(4) レーシック手術後・美容整形後・アートメイク施術後の方は、施術をお断りする場合があります。","(5) 体調により、接着剤の揮発成分が目に刺激を与える場合があります。","(6) お客様のまつ毛の状態により、ご希望の本数・デザインに対応できない場合があります。","(7) 妊娠中の方は、アレルギー反応のリスクが高まる場合があります。","(8) 施術後の返金・払い戻しはお受けしておりません。","(9) 施術写真をSNS等に掲載させていただく場合があります。掲載NGの方は事前にお申し出ください。"]},{"title":"アイブロウ注意事項","items":["(1) 施術前にカウンセリングを実施します。ご質問には正確にお答えください。","(2) 施術中に違和感を感じた場合は、すぐにお申し出ください。施術を中止する場合があります。","(3) 施術後に刺激やかゆみを感じた場合は、当サロンまでご連絡ください。","(4) 施術後2〜3日間は、刺激成分を含む化粧品（クレンジング、ピーリング、ニキビケア化粧品等）のご使用をお控えください。","(5) 肌トラブルを完全に回避することはできません。施術後のトラブルについては責任を負いかねます。","(6) アレルギー・皮膚疾患・過去にトラブルがあった方は、必ず事前にお申し出ください。","(7) 敏感肌の方やアレルギーがご心配な方は、パッチテストを実施できます。","(8) 注意事項を遵守いただくことで、肌トラブルのリスクを低減できます。","(9) ご不安な点がございましたら、お気軽にスタッフにご確認ください。","(10) 施術写真をSNS等に掲載させていただく場合があります。掲載NGの方は事前にお申し出ください。"]},{"title":"ネイル注意事項","items":["(1) 施術中に痛みや違和感を感じた場合は、すぐにお申し出ください。","(2) 皮膚疾患やグリーンネイルがある場合、施術を制限させていただく場合があります。判断は自己責任となります。","(3) 施術後の亀裂・破損については自己責任となり、修正はお受けしておりません。","(4) 事前確認なくのクレームには対応いたしかねます。","(5) 施術後のお直し・クレーム・返金は一切お受けしておりません。"]},{"title":"クリスティーナ注意事項","items":["(1) 天然素材を主成分としたトリートメント法です。","(2) 医療行為ではなく、素肌美を目的とした施術です。","(3) ピーリング剤使用時に刺激や痛みを感じる場合がありますが、通常数日で治まります。","(4) ターンオーバーの促進により、一時的にくすみやシミが目立つ場合があります。","(5) カウンセリング内容をご確認いただき、説明を理解した上でホームケアを実施してください。","(6) 施術後はむやみに触ったり掻いたりしないでください。","(7) 効果には個人差があり、健康状態の影響を受ける場合があります。","(8) カウンセリングで申告されなかったことに起因するトラブルについては責任を負いかねます。","(9) 営業妨害や誹謗中傷に該当するSNS投稿はお控えください。","(10) ご署名後、いかなる理由でも払い戻しはいたしません。"]},{"title":"耳ツボジュエリー注意事項","items":["(1) アレルギーや肌トラブルが生じた場合は自己責任となります。","(2) スタッフが丁寧に装着いたしますが、取れやすい場合もございます。","(3) 取れた場合は衛生上破棄していただき、お直しは実施しておりません。","(4) ご署名後、いかなる場合でも払い戻しはいたしません。"]}]',
  '[{"name":"customer_name","label":"お名前","type":"text","required":true},{"name":"customer_birthday","label":"生年月日","type":"date","required":true},{"name":"customer_phone","label":"電話番号","type":"tel","required":true},{"name":"customer_occupation","label":"ご職業","type":"text","required":false},{"name":"customer_visit_reason","label":"ご来店のきっかけ","type":"text","required":false}]',
  'v2025-10-26',
  1
);
